func collectActiveUsers(users []User, cutoff time.Time) []string {
    activeUsers := make([]string, 0, len(users))

    for _, user := range users {
        if !user.IsOnline || !user.LastSeenAt.After(cutoff) {
            continue
        }

        activeUsers = append(activeUsers, user.Name)
    }

    return activeUsers
}

func clampScore(score, min, max int) int {
    if score < min {
        return min
    }

    if score > max {
        return max
    }

    return score
}

func buildSummary(project Project) (string, error) {
    if project.Name == "" {
        return "", fmt.Errorf("missing project name")
    }

    summary := strings.ToLower(project.Name + ":" + project.Branch)
    summary = strings.ReplaceAll(summary, " ", "-")

    return summary, nil
}

func topScores(entries []Entry) []Entry {
    ranked := slices.Clone(entries)

    slices.SortFunc(ranked, func(left, right Entry) int {
        return right.Score - left.Score
    })

    return ranked[:min(5, len(ranked))]
}

func groupPostsByTag(posts []Post) map[string][]string {
    grouped := make(map[string][]string)

    for _, post := range posts {
        for _, tag := range post.Tags {
            grouped[tag] = append(grouped[tag], post.Slug)
        }
    }

    return grouped
}

func loadConfig(path string) (Config, error) {
    data, err := os.ReadFile(path)
    if err != nil {
        return Config{}, fmt.Errorf("read config: %w", err)
    }

    var config Config
    if err := json.Unmarshal(data, &config); err != nil {
        return Config{}, fmt.Errorf("parse config: %w", err)
    }

    return config, nil
}

func fetchWithTimeout(ctx context.Context, url string) ([]byte, error) {
    ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
    defer cancel()

    request, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
    if err != nil {
        return nil, err
    }

    response, err := http.DefaultClient.Do(request)
    if err != nil {
        return nil, err
    }
    defer response.Body.Close()

    return io.ReadAll(response.Body)
}

func runWorkers(jobs []Job) []Result {
    results := make([]Result, len(jobs))
    var wg sync.WaitGroup

    for index, job := range jobs {
        wg.Add(1)
        go func(i int, j Job) {
            defer wg.Done()
            results[i] = j.Execute()
        }(index, job)
    }

    wg.Wait()
    return results
}

type Counter struct {
    mu    sync.Mutex
    value int
}

func (c *Counter) Increment() {
    c.mu.Lock()
    defer c.mu.Unlock()
    c.value++
}

func (c *Counter) Value() int {
    c.mu.Lock()
    defer c.mu.Unlock()
    return c.value
}

func uniqueStrings(values []string) []string {
    seen := make(map[string]struct{}, len(values))
    unique := make([]string, 0, len(values))

    for _, value := range values {
        if _, exists := seen[value]; exists {
            continue
        }
        seen[value] = struct{}{}
        unique = append(unique, value)
    }

    return unique
}
